set -e
export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/sw01
rm -rf $D; mkdir -p $D; cd $D
base64 -d << 'EOB64' > /tmp/sw01.zip

EOB64
unzip -oq /tmp/sw01.zip -d $D
for t in _sw1 _sw2; do /opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source $t.tcl > $t.log 2>&1; grep -q DONE_$t $t.log && echo OK $t || { echo FAIL $t; grep -m2 ERROR $t.log; }; done
tar czf /tmp/sw01_out.tgz *.bit *.pips
echo SW01DONE
